const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2021-01-01';
  const endDate = '2021-01-31';

  // Get Namibia's geometry
  const namibia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Namibia'))
    .first()
    .geometry();

  if (!namibia) {
    console.log("Error: Could not retrieve Namibia's geometry.");
    console.log("D"); // Indicates a data access/name issue
    return;
  }

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(namibia);

  const collectionSize = await chirps.size().getInfo();
  console.log(`CHIRPS images for Jan 2021: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No CHIRPS images found for January 2021 over Namibia.");
    console.log("C1");
    return;
  }

  // Sum all daily precipitation images for the period
  const totalPrecipitation = chirps.sum();

  // 3. Processing & Calculation
  const scale = 5000; // CHIRPS resolution is ~5.5km, use 5km scale for aggregation
  const maxPixels = 1e10; // Increase maxPixels for large regions

  // Reduce the total precipitation image to get the mean over Namibia
  const meanPrecipitationMm = await totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: scale,
    maxPixels: maxPixels
  }).get('precipitation').getInfo();

  // Check for valid pixels and calculation failure
  const pixelCount = await totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: scale,
    maxPixels: maxPixels
  }).get('precipitation').getInfo();

  console.log(`Valid pixels in Namibia: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after filtering and reducing.");
    console.log("C2");
    return;
  }

  if (meanPrecipitationMm === null || isNaN(meanPrecipitationMm)) {
    console.log("Calculation resulted in None/NaN for mean precipitation.");
    console.log("C3");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const meanPrecipitationInches = meanPrecipitationMm / 25.4;

  // 4. Validation & Final Answer
  const thresholdInches = 7;
  const didExceedThreshold = meanPrecipitationInches > thresholdInches;

  console.log(`Mean rainfall in Namibia (Jan 2021): ${meanPrecipitationInches.toFixed(2)} inches`);

  if (didExceedThreshold) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
